// The approval lane's store (docs/design/round7/studio/APPROVAL-LANE.md; main's go, 2026-11-10; round 8 dc-r8-selection-
// before-generation, layer 3). A generated Stagecraft spec reaches a child only when it was approved OFFLINE:
//   1. generated by a Foundry spec call (scripts/approve-generate.mjs; main runs it, the key is main's)
//   2. passed today's predicate checks and a local render at p360, p412 and l1366 (scripts/approve-check.mjs)
//   3. passed a rubric pass by a separate Claude judge that did not write it (the verdict, the judge's prompt and the
//      rendered images' hashes are kept)
//   4. written here, in git: data/studio-approved/<topicId>/<id>.json — the commit IS the approval.
// The runtime never calls a judge: the tray gate (server/forge3/tray-gate.js) shows a generated spec only when its hash is
// in this store, at a size its render passed; anything else is refused exactly as before.
//
// An approved piece carries what it is FOR — { topic, skill, misconceptionId, beat } — and a `because`: it is chosen only for
// a child who holds that mix-up; any other child gets the script's own board.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
export const STORE_DIR = path.join(REPO, "data/studio-approved");
export const JUDGED_SIZES = Object.freeze(["p360", "p412", "l1366"]);
/** main 2026-11-10: a piece is judged where it can be PLAYED — p412 and l1366; at p360 every Studio v2 world is refused (its twin
 *  is a word card), so a record stores p360 false. */
export const APPROVAL_SIZES = Object.freeze(["p412", "l1366"]);

/** The four pilots' first targets: one generated visual each, aimed at one named mix-up of the topic's kit. */
export const PILOT_TARGETS = Object.freeze([
  // (main 2026-11-10, after the retry judge: each `how` in the engine's own terms)
  { topicId: "c4-maths-ch05-t01", archetype: "slice-at@1", misconceptionId: "c4-maths-ch05-t01-m-unequal-parts",
    how: "every wave's sub must agree with its own items: a sub that names a number of parts names exactly the items' parts value (a wave of {parts: 4} says chaar, never teen); one count per wave; plain Roman Hinglish, no Devanagari" },
  { topicId: "c5-maths-ch02-t01", archetype: "catch-on-line@1", misconceptionId: "c5-maths-ch02-t01-m-count-marks",
    how: "ticks is the number of EQUAL GAPS from 0 to 1 (ticks 4 draws 3 marks). Set every wave's ticks to its fractions' denominator (thirds: ticks 3) and scaffoldTicks equal to ticks; every item lands on a mark; a sub names a gap count only when it equals ticks; Roman Hinglish only" },
  // (catch-on-line's pods hold ONE value — two labels in a pod must be equal: the mix-up is shown by catching unit fractions one
  // at a time on one line, never by pairing two to compare; the first two calls paired 1/4 with 1/8 and fell back)
  { topicId: "c5-maths-ch02-t02", archetype: "catch-on-line@1", misconceptionId: "c5-maths-ch02-t02-m-bigger-denominator",
    how: "catch unit fractions one at a time on ONE 0 to 1 line (1/2, 1/3, 1/4, 1/6, 1/8, one fraction per item, never two different fractions in one item), so 1/8 lands nearest 0 and 1/2 farthest; a later wave may mark only the half; no title or sub states the rule she must find (never that a bigger bottom number makes a smaller piece): they say only what to do" },
  { topicId: "c6-maths-ch06-t01", archetype: "area-claim@1", misconceptionId: "c6-maths-ch06-t01-m-area-perimeter",
    how: "every string plain class-6 Hinglish in Roman script: no stake, claim, plot, sq or units in English. The goal reads '<area> <n> <sq> <units>' and '<perimeter> <n> <units>', so set sq to varg and units to ikai (area 40 varg ikai); coach like Grid par khet banao; claim like BAN GAYA" },
]);

/** The canonical JSON of a value (keys sorted): two specs that say the same thing hash the same. */
const canon = (v) => (Array.isArray(v) ? v.map(canon) : v && typeof v === "object" ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, canon(v[k])])) : v);
/** A spec's identity: sha256 of its archetype and canonical spec, 32 hex. */
export const specHash = (archetype, spec) => createHash("sha256").update(JSON.stringify({ a: String(archetype ?? ""), s: canon(spec ?? null) })).digest("hex").slice(0, 32);
export const fileHash = (file) => createHash("sha256").update(fs.readFileSync(file)).digest("hex");

/**
 * Where a piece aimed at `misconceptionId` sits in the topic's script: the remediation that fires for that mix-up (Brain's
 * scriptBeat.beatId `rem:<misconceptionId>`, the id the seam matches), after the first scripted check that targets it
 * (`<skillId>:<checkId>`). → { skillId, beat, when, check } or null.
 */
export function beatFor(topicId, misconceptionId) {
  try {
    const j = JSON.parse(fs.readFileSync(path.join(REPO, "data/lesson-scripts", `${topicId}.json`), "utf8"));
    for (const [i, sk] of (j.skills ?? []).entries()) {
      const skillId = sk.id ?? `${topicId}-s${i + 1}`;
      for (const c of sk.checks ?? []) if (c?.targets === misconceptionId && c.id) return { skillId, beat: `rem:${misconceptionId}`, when: "remediation", check: `${skillId}:${c.id}` };
    }
  } catch { /* no script */ }
  return null;
}

let memo = null, storeDir = STORE_DIR;
/** Tests only: read the store from another folder (null: back to data/studio-approved). */
export const _useStore = (dir) => { storeDir = dir ?? STORE_DIR; memo = null; };
/** Every approved record in the store (`approved: true`, the judge's pass, rendered legible at ≥ 1 judged size). Read once. */
export function loadApproved({ fresh = false, dir = storeDir } = {}) {
  if (memo && !fresh && dir === storeDir) return memo;
  const out = new Map();
  try {
    for (const t of fs.existsSync(dir) ? fs.readdirSync(dir) : []) {
      const d = path.join(dir, t);
      if (!fs.statSync(d).isDirectory()) continue;
      for (const f of fs.readdirSync(d).filter((x) => x.endsWith(".json") && x !== "manifest.json")) {
        try {
          const r = JSON.parse(fs.readFileSync(path.join(d, f), "utf8"));
          // (rendered at all three sizes; shown only at the sizes that passed — the tray gate reads byViewport per device)
          const okSizes = JUDGED_SIZES.some((s) => r?.render?.byViewport?.[s] === true);
          // (the hash must be the spec's own: a record edited by hand after approval is not approved)
          if (r?.approved === true && okSizes && r.judge?.verdict === "pass" && r.hash === specHash(r.archetype, r.spec)) out.set(r.hash, r);
        } catch { /* a broken record is not approved */ }
      }
    }
  } catch { /* no store */ }
  if (dir === storeDir) memo = out;
  return out;
}
export const _resetApproved = () => { memo = null; };

/** The tray gate's verdict for a generated spec: { byViewport, approved: id } when its hash is approved, else null. */
export function approvedVerdict(archetype, spec) {
  const r = loadApproved().get(specHash(archetype, spec));
  return r ? { pass: true, approved: r.id, byViewport: Object.fromEntries(JUDGED_SIZES.map((s) => [s, r.render.byViewport[s] === true])) } : null;
}

/** The approved pieces a round's reader may choose for a child who holds `misconceptionId` on `topicId` (with `because`). */
export function approvedFor({ topicId, misconceptionId }) {
  return [...loadApproved().values()].filter((r) => r.source !== "catalogue" && r.for?.topic === topicId && (!misconceptionId || r.for?.misconceptionId === misconceptionId))
    .map((r) => ({ id: r.id, hash: r.hash, archetype: r.archetype, spec: r.spec, for: r.for, because: r.because }));
}

/**
 * main's ruling (2026-11-10, after the 20-topic sample: 11 of 20 with a content fault, 2 wrong keys): a CATALOGUE piece reaches a
 * child only with a judged pass in this store, exactly like a generated piece. Switch STUDIO_CATALOGUE_JUDGED (default "on";
 * "off" serves the certified catalogue as before). An engine's own reviewed default spec is code, not catalogue content: it needs
 * no judgement. Reverse when a fresh random sample of 50 unjudged pieces passes the rubric at 95% or better.
 */
export const catalogueNeedsJudge = (env = process.env) => String(env.STUDIO_CATALOGUE_JUDGED ?? "on").trim().toLowerCase() !== "off";
let defaults = null;
/** Is `spec` the archetype's reviewed engine default (shared/studio-spec*.ts defaultSpec)? */
export async function _loadDefaults() {
  if (defaults) return defaults;
  const [{ ENGINE_SPECS }, { ENGINE_SPECS_EXT }] = await Promise.all([import("../../shared/studio-spec.ts"), import("../../shared/studio-spec-ext/index.ts")]);
  defaults = new Set(Object.entries({ ...ENGINE_SPECS, ...ENGINE_SPECS_EXT }).filter(([, d]) => d?.defaultSpec).map(([a, d]) => specHash(a, d.defaultSpec)));
  return defaults;
}
export const isReviewedDefault = (archetype, spec) => !!defaults && defaults.has(specHash(archetype, spec));
await _loadDefaults().catch(() => null);
